import{_ as a,o as r,c as t,a5 as o}from"./chunks/framework.CXvGqWf0.js";const u=JSON.parse('{"title":"漫画 · 第 30 话 @property：给变量上户口","description":"","frontmatter":{},"headers":[],"relativePath":"comics/css/EP.30-property.md","filePath":"comics/css/EP.30-property.md","lastUpdated":1793421609000}'),i={name:"comics/css/EP.30-property.md"};function s(l,e,n,c,d,p){return r(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="漫画-·-第-30-话-property-给变量上户口" tabindex="-1">漫画 · 第 30 话 @property：给变量上户口 <a class="header-anchor" href="#漫画-·-第-30-话-property-给变量上户口" aria-label="Permalink to &quot;漫画 · 第 30 话 @property：给变量上户口&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../../docs/css/20-property">docs/css/20-property.md</a> ｜ 原画：<a href="./EP.30-property.svg">EP.30-property.svg</a></p></blockquote><h2 id="登场角色" tabindex="-1">登场角色 <a class="header-anchor" href="#登场角色" aria-label="Permalink to &quot;登场角色&quot;">​</a></h2><ul><li><strong>像素酱</strong>：CSS 造型师，本话主角。给主题切换加颜色过渡，<code>transition: --c 1s</code> 写完满心欢喜，结果颜色 1 秒后瞬间跳变——又退回 JS 逐帧改值的老路。</li><li><strong>标签君</strong>：HTML5 结构师，搬出 <code>@property</code>——变量注册进类型系统后，浏览器知道怎么补间，颜色、角度、百分比、长度全部可动画。</li></ul><h2 id="剧情梗概" tabindex="-1">剧情梗概 <a class="header-anchor" href="#剧情梗概" aria-label="Permalink to &quot;剧情梗概&quot;">​</a></h2><p>变量章（EP.06）讲了 <code>var()</code> 的运行时替换，动画章（EP.02）讲了 transition/keyframes，但两者结合时有个暗坑：未注册变量是字符串，动画只能跳变。本话用 <code>@property</code> 把两块拼图咬合——syntax 声明类型、inherits 控制继承、initial-value 兜底，变量从此进入浏览器的插值系统。</p><h2 id="分格解读" tabindex="-1">分格解读 <a class="header-anchor" href="#分格解读" aria-label="Permalink to &quot;分格解读&quot;">​</a></h2><h3 id="格1-·-痛点现场" tabindex="-1">格1 · 痛点现场 <a class="header-anchor" href="#格1-·-痛点现场" aria-label="Permalink to &quot;格1 · 痛点现场&quot;">​</a></h3><p>未注册变量在浏览器眼里是字符串：<code>red → blue</code>、<code>0% → 100%</code>、<code>0deg → 360deg</code>，前后两个字符串之间没有「中间帧」，动画退化为延迟跳变。想要平滑效果只能回退到 rAF + JS 手写插值。</p><h3 id="格2-·-机制登场" tabindex="-1">格2 · 机制登场 <a class="header-anchor" href="#格2-·-机制登场" aria-label="Permalink to &quot;格2 · 机制登场&quot;">​</a></h3><p><code>@property --c { syntax: &quot;&lt;color&gt;&quot;; inherits: false; initial-value: transparent; }</code> 三件套把变量注册进类型系统。syntax 支持 color/length/number/percentage/angle/time 等；赋值不合法时静默回退到 initial-value；JS 侧可用 <code>CSS.registerProperty</code> 动态注册。</p><h3 id="格3-·-落地收束" tabindex="-1">格3 · 落地收束 <a class="header-anchor" href="#格3-·-落地收束" aria-label="Permalink to &quot;格3 · 落地收束&quot;">​</a></h3><p>四大实战场景：颜色过渡无黑屏（主题切换逐色插值）、color-mix 参数动画（渐变混合比例平滑推移）、transform 多变量串联（--tx/--s/--rot 各自动画，一条 transition 控三维）、锥形渐变进度环（角度变量驱动纯 CSS 充能动画）。</p><h2 id="码叔划重点" tabindex="-1">码叔划重点 <a class="header-anchor" href="#码叔划重点" aria-label="Permalink to &quot;码叔划重点&quot;">​</a></h2><ol><li>syntax / inherits / initial-value 三件套注册后，变量才可被浏览器插值动画。</li><li>transition 目标是变量本身：transition: --x，引用它的属性随变量逐帧重算。</li><li>赋值不合法静默回退 initial-value——调试时看 DevTools 的 invalid 标记。</li></ol><h2 id="自测一题" tabindex="-1">自测一题 <a class="header-anchor" href="#自测一题" aria-label="Permalink to &quot;自测一题&quot;">​</a></h2><p><strong>问</strong>：<code>transition: width 1s; width: var(--w);</code> 配合 <code>--w: 100px → 200px</code> 的变化，能实现平滑动画吗？为什么？</p><p><strong>答</strong>：不能。<code>transition: width</code> 监听的是 <strong>width 计算值的变化</strong>，而 <code>--w</code> 未注册时只是字符串替换，width 从 100px 变 200px 是一次性跳变（字符串替换不算可过渡的计算值变化）。正确姿势：先 <code>@property --w { syntax: &quot;&lt;length&gt;&quot;; }</code> 注册，再写 <code>transition: --w 1s</code>——动画目标是变量本身，width 引用 var(--w) 随变量逐帧重算。</p><h2 id="动手实验" tabindex="-1">动手实验 <a class="header-anchor" href="#动手实验" aria-label="Permalink to &quot;动手实验&quot;">​</a></h2><ul><li>注册 vs 未注册对比 + color-mix 参数 + transform 串联 + 锥形渐变进度环：<a href="./../../examples/css/20-property/index-01-property.html">examples/css/20-property/</a></li></ul><h2 id="系列结语" tabindex="-1">系列结语 <a class="header-anchor" href="#系列结语" aria-label="Permalink to &quot;系列结语&quot;">​</a></h2><p>「现代 CSS 架构」三部曲完结：层叠层（EP.23）管优先级、嵌套（EP.28）管书写结构、@scope（EP.29）管作用域隔离，@property（EP.30）让变量系统真正可动画——四件装备，覆盖了现代组件化样式的四大支柱。</p>',22)])])}const m=a(i,[["render",s]]);export{u as __pageData,m as default};
